import { useToolbarItem } from '@dreadnought/react/logic';
import { ToolbarAdapter } from '@dreadnought/react/unstyled';
function Tool({ value }: { value: string }) {
  const { itemProps } = useToolbarItem<HTMLButtonElement>({ value });
  return <button {...itemProps}>{value}</button>;
}
export function Example() {
  return <ToolbarAdapter aria-label='Команды'><Tool value='save' /><Tool value='copy' /><Tool value='download' /></ToolbarAdapter>;
}

